215	  // ---------------------------------------------------------------------------
216	  // Sentiment donut chart
217	  // ---------------------------------------------------------------------------
218	
219	  generateSentimentDonut(
220	    sentimentDistribution: Record<string, number>,
221	    date: string,
222	  ): string {
223	    log.info(`Generating sentiment donut for ${date}`);
224	
225	    const entries = Object.entries(sentimentDistribution).filter(([, v]) => v > 0);
226	    const total = entries.reduce((s, [, v]) => s + v, 0);
227	
228	    const w = 600;
229	    const h = 500;
230	    const cx = 300;
231	    const cy = 250;
232	    const outerR = 120;
233	    const innerR = 60;
234	
235	    if (total === 0) {
236	      return this.emptySvg(`情感分布 — ${date}`, '暂无情感数据', date);
237	    }
238	
239	    const colors = this.colorScheme === 'colorblind'
240	      ? SENTIMENT_COLORS_COLORBLIND
241	      : SENTIMENT_COLORS_DEFAULT;
242	
243	    // Sort entries for consistent rendering: positive, neutral, negative
244	    const sorted = ['positive', 'neutral', 'negative']
245	      .filter((k) => entries.some(([key]) => key === k))
246	      .map((k) => [k, entries.find(([key]) => key === k)![1]] as [string, number]);
247	
248	    const paths: string[] = [];
249	    const legendItems: string[] = [];
250	
251	    // Start from the top (-90 degrees)
252	    let currentAngle = -90;
253	
254	    sorted.forEach(([key, value], idx) => {
255	      const pct = value / total;
256	      const sweepDeg = pct * 360;
257	      const endAngle = currentAngle + sweepDeg;
258	
259	      const color = colors[key] || '#6B7280';
260	
261	      // Add pattern defs for colorblind
262	      if (this.colorScheme === 'colorblind') {
263	        // Use texture via pattern
264	        paths.push(donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle));
265	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR - 2, outerR + 2, currentAngle, endAngle)}" fill="none" stroke="#333" stroke-width="1" />`);
266	      } else {
267	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle)}" fill="${color}" />`);
268	      }
269	
270	      // Legend
271	      const legendY = 150 + idx * 30;
272	      legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
273	      legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
274	
275	      currentAngle = endAngle;
276	    });
277	
278	    const svgContent = [
279	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">情感分布 — ${date}</text>`,
280	      paths.join('\n'),
281	      `  <text class="value" x="${cx}" y="${cy - 8}" text-anchor="middle" font-size="24" font-weight="bold" fill="#111827">N=${total}</text>`,
282	      `  <text class="note" x="${cx}" y="${cy + 12}" text-anchor="middle" font-size="12">条</text>`,
283	      legendItems.join('\n'),
284	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
285	    ].join('\n');
286	
287	    return wrapSvg(svgContent, w, h);
288	  }
