290	  // ---------------------------------------------------------------------------
291	  // Trend radar chart
292	  // ---------------------------------------------------------------------------
293	
294	  generateTrendRadar(trends: TrendAnalysis, date: string): string {
295	    log.info(`Generating trend radar for ${date}`);
296	
297	    const w = 600;
298	    const h = 600;
299	    const cx = 300;
300	    const cy = 300;
301	    const axisLen = 200;
302	
303	    type TrendDimensionKey = 'technology' | 'application' | 'policy' | 'capital';
304	
305	    interface AxisDef {
306	      key: TrendDimensionKey;
307	      label: string;
308	      angleDeg: number; // clockwise from positive x-axis
309	    }
310	
311	    const axes: AxisDef[] = [
312	      { key: 'technology', label: '技术', angleDeg: -90 },
313	      { key: 'application', label: '应用', angleDeg: 0 },
314	      { key: 'policy', label: '政策', angleDeg: 90 },
315	      { key: 'capital', label: '资本', angleDeg: 180 },
316	    ];
317	
318	    // Helper to get data point on an axis
319	    const getPoint = (angleDeg: number, ratio: number) =>
320	      polarPoint(cx, cy, axisLen * ratio, angleDeg);
321	
322	    // Grid polygons (0.25, 0.5, 0.75, 1.0)
323	    const gridPolygons: string[] = [];
324	    for (const ratio of [0.25, 0.5, 0.75, 1.0]) {
325	      const pts = axes.map((a) => {
326	        const p = getPoint(a.angleDeg, ratio);
327	        return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
328	      });
329	      gridPolygons.push(`  <polygon class="grid" points="${pts.join(' ')}" fill="none" />`);
330	    }
331	
332	    // Axes lines from center to edge
333	    const axisLines: string[] = [];
334	    const axisLabels: string[] = [];
335	    const refLabels: string[] = [];
336	    axes.forEach((a) => {
337	      const tip = getPoint(a.angleDeg, 1.0);
338	      axisLines.push(`  <line class="axis" x1="${cx}" y1="${cy}" x2="${tip.x.toFixed(1)}" y2="${tip.y.toFixed(1)}" />`);
339	
340	      // Label at tip + offset
341	      const offset = 20;
342	      let lx = tip.x;
343	      let ly = tip.y;
344	      let anchor = 'middle';
345	      if (a.angleDeg === -90) { ly = tip.y - offset; anchor = 'middle'; }
346	      else if (a.angleDeg === 0) { lx = tip.x + offset; anchor = 'start'; }
347	      else if (a.angleDeg === 90) { ly = tip.y + offset; anchor = 'middle'; }
348	      else if (a.angleDeg === 180) { lx = tip.x - offset; anchor = 'end'; }
349	
350	      axisLabels.push(`  <text class="label" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}" font-weight="bold" font-size="14">${a.label}</text>`);
351	
352	      // Ref labels at 0.25 intervals
353	      for (const r of [0.25, 0.5, 0.75]) {
354	        const rp = getPoint(a.angleDeg, r);
355	        refLabels.push(`  <text class="ref-text" x="${rp.x.toFixed(1)}" y="${rp.y.toFixed(1) + 3}" text-anchor="${a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle'}">${r.toFixed(2)}</text>`);
356	      }
357	    });
358	
359	    // Data polygon
360	    const dataPoints = axes.map((a) => {
361	      const dim = trends[a.key];
362	      const conf = dim?.confidence ?? 0;
363	      const p = getPoint(a.angleDeg, conf);
364	      return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
365	    });
366	
367	    // Data value labels at each axis
368	    const dataLabels: string[] = [];
369	    axes.forEach((a) => {
370	      const dim = trends[a.key];
371	      const conf = dim?.confidence ?? 0;
372	      const p = getPoint(a.angleDeg, conf);
373	      const off = 12;
374	      const dx = a.angleDeg === 180 ? -off : a.angleDeg === 0 ? off : 0;
375	      const dy = a.angleDeg === -90 ? -off : a.angleDeg === 90 ? off : 0;
376	      const anchor = a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle';
377	      dataLabels.push(`  <text class="value" x="${(p.x + dx).toFixed(1)}" y="${(p.y + dy).toFixed(1)}" text-anchor="${anchor}" font-size="13" font-weight="bold" fill="#3B82F6">${conf.toFixed(2)}</text>`);
378	    });
379	
380	    const svgContent = [
381	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">四维趋势雷达 — ${date}</text>`,
382	      gridPolygons.join('\n'),
383	      axisLines.join('\n'),
384	      refLabels.join('\n'),
385	      axisLabels.join('\n'),
386	      `  <polygon points="${dataPoints.join(' ')}" fill="rgba(59, 130, 246, 0.2)" stroke="#3B82F6" stroke-width="2" />`,
387	      dataLabels.join('\n'),
388	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
389	    ].join('\n');
390	
391	    return wrapSvg(svgContent, w, h);
392	  }
393	
394	  // ---------------------------------------------------------------------------
395	  // Empty state helper
396	  // ---------------------------------------------------------------------------
397	
398	  private emptySvg(title: string, message: string, date?: string): string {
399	    const w = this.width;
400	    const h = this.height;
401	    const dateStr = date ?? '';
402	    const svgContent = [
403	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">${title}</text>`,
404	      `  <text class="value" x="${w / 2}" y="${h / 2}" text-anchor="middle">${message}</text>`,
405	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine${dateStr ? ` — ${dateStr}` : ''}</text>`,
406	    ].join('\n');
407	    return wrapSvg(svgContent, w, h);
408	  }
409	}
